package com.intermarche.backoffice.engine.operator;
import com.intermarche.backoffice.domain.operator.*;import com.intermarche.backoffice.domain.store.Store;import com.intermarche.backoffice.domain.util.DateTimeProvider;import com.intermarche.backoffice.engine.fieldops.StockCommands;
import jakarta.enterprise.context.ApplicationScoped;import jakarta.inject.Inject;import jakarta.transaction.Transactional;import jakarta.ws.rs.*;import java.util.*;import java.time.*;
@ApplicationScoped @Transactional public class OperatorShiftService {
 @Inject OperatorSupportService support;@Inject StockCommands receipts;@Inject jakarta.persistence.EntityManager em;
 @org.eclipse.microprofile.openapi.annotations.media.Schema(name="OperatorShiftInput") public static class Input {public Long storeId,shiftId;public String requestKey,action,state,reason,expectedRevision;public Integer goalLines;}
 private static final Set<String> STATES=Set.of("PREPARATION","WAIT_STOCK","WAIT_EQUIPMENT","WAIT_SYSTEM","BREAK");
 private String revision(OperatorShift s){OperatorShiftInterval last=OperatorShiftInterval.find("shift=?1 order by id desc",s).firstResult();return CommandCanonical.hash(support.encode(Arrays.asList(s.id,s.version,s.goalLines,s.endedAt,last==null?null:Arrays.asList(last.id,last.state,last.endedAt))));}
 private OperatorShift current(Store store){return OperatorShift.find("store=?1 and principal=?2 and endedAt is null order by id desc",store,support.actor()).firstResult();}
 public Object read(Long storeId){var store=support.store(storeId);var s=current(store);return s==null?Map.of("active",false):view(s);}
 public Object change(Input i){if(i==null)throw new BadRequestException();var store=support.locked(i.storeId);String hash=CommandCanonical.hash(support.encode(i));var previous=receipts.previous(store,i.requestKey,hash);if(previous!=null)return receipts.value(previous);var now=DateTimeProvider.now();var s=current(store);
  if("START".equals(i.action)){if(s!=null)throw new OperatorFailure(409,"SHIFT_ALREADY_STARTED","Votre poste est déjà ouvert");s=new OperatorShift();s.store=store;s.principal=support.actor();s.startedAt=now;s.persistAndFlush();interval(s,"PREPARATION",null,now);}
  else{if(s==null||!Objects.equals(s.id,i.shiftId))throw new NotFoundException();if(!Objects.equals(revision(s),i.expectedRevision))throw new OperatorFailure(409,"STALE_SHIFT","Le poste a changé : actualisez");if(!Set.of("STATE","FINISH").contains(i.action==null?"":i.action))throw new BadRequestException();if("STATE".equals(i.action)&&!STATES.contains(i.state==null?"":i.state))throw new BadRequestException("État inconnu");if(i.reason!=null&&i.reason.length()>500)throw new BadRequestException("Motif limité à 500 caractères");var open=OperatorShiftInterval.<OperatorShiftInterval>find("shift=?1 and endedAt is null",s).firstResult();if(open!=null)open.endedAt=now;if("FINISH".equals(i.action))s.endedAt=now;else interval(s,i.state,i.reason,now);s.updatedAt=now;em.flush();}
  var profile=OperatorProfile.<OperatorProfile>find("store=?1 and principal=?2",store,support.actor()).firstResult();if(profile==null){profile=new OperatorProfile();profile.store=store;profile.principal=support.actor();profile.persist();}profile.state=s.endedAt!=null?"FINISHED":"BREAK".equals(i.state)?"PAUSED":"AVAILABLE";
  return receipts.record(store,i.requestKey,hash,"OPERATOR_SHIFT",view(s));
 }
 private static void interval(OperatorShift s,String state,String reason,LocalDateTime at){var p=new OperatorShiftInterval();p.shift=s;p.state=state;p.reason=reason;p.startedAt=at;p.persist();}
 public static void serviceState(Store store,String actor,String state){var s=OperatorShift.<OperatorShift>find("store=?1 and principal=?2 and endedAt is null",store,actor).firstResult();if(s==null)return;var current=OperatorShiftInterval.<OperatorShiftInterval>find("shift=?1 and endedAt is null",s).firstResult();var at=DateTimeProvider.now();if("FINISHED".equals(state)){if(current!=null)current.endedAt=at;s.endedAt=at;return;}String target="PAUSED".equals(state)?"BREAK":current!=null&&"BREAK".equals(current.state)?"PREPARATION":null;if(target!=null&&(current==null||!target.equals(current.state))){if(current!=null)current.endedAt=at;interval(s,target,null,at);}}
 public Object goal(Input i){if(i==null)throw new BadRequestException();support.manager();var store=support.locked(i.storeId);var hash=CommandCanonical.hash(support.encode(i));var previous=receipts.previous(store,i.requestKey,hash);if(previous!=null)return receipts.value(previous);OperatorShift s=OperatorShift.find("id=?1 and store=?2",i.shiftId,store).firstResult();if(s==null)throw new NotFoundException();if(!Objects.equals(revision(s),i.expectedRevision)||s.endedAt!=null)throw new OperatorFailure(409,"STALE_SHIFT","Actualisez le poste actif");if(i.goalLines!=null&&(i.goalLines<1||i.goalLines>100000))throw new BadRequestException("Objectif de 1 à 100000 lignes");s.goalLines=i.goalLines;em.flush();return receipts.record(store,i.requestKey,hash,"OPERATOR_SHIFT_GOAL",view(s));}
 public Object active(Long storeId){support.manager();var store=support.store(storeId);return OperatorShift.<OperatorShift>list("store=?1 and endedAt is null order by id",store).stream().map(this::view).toList();}
 private Map<String,Object> view(OperatorShift s){var now=s.endedAt==null?DateTimeProvider.now():s.endedAt;var v=new LinkedHashMap<String,Object>();v.put("id",s.id);v.put("principal",s.principal);v.put("active",s.endedAt==null);v.put("startedAt",s.startedAt);v.put("endedAt",s.endedAt);v.put("revision",revision(s));v.put("goalLines",s.goalLines);var durations=new TreeMap<String,Long>();String state="FINISHED";for(var p:OperatorShiftInterval.<OperatorShiftInterval>list("shift=?1 order by id",s)){var end=p.endedAt==null?now:p.endedAt;durations.merge(p.state,Math.max(0,Duration.between(p.startedAt,end).getSeconds()),Long::sum);if(p.endedAt==null){state=p.state;v.put("stateReason",p.reason);v.put("stateStartedAt",p.startedAt);v.put("stateSeconds",Math.max(0,Duration.between(p.startedAt,now).getSeconds()));}}v.put("state",state);v.put("seconds",durations);v.put("timeBasis","DECLARED");var rows=em.createQuery("select q.metric,q.unit,sum(q.quantity),count(distinct q.lineId) from ActivityQuantity q where q.store=?1 and q.actor=?2 and q.createdAt>=?3 and q.createdAt<=?4 group by q.metric,q.unit order by q.metric,q.unit",Object[].class).setParameter(1,s.store).setParameter(2,s.principal).setParameter(3,s.startedAt).setParameter(4,now).getResultList();v.put("quantities",rows.stream().map(r->Map.of("metric",r[0],"unit",r[1],"quantity",r[2],"lines",r[3])).toList());v.put("preparedLines",em.createQuery("select count(distinct q.lineId) from ActivityQuantity q where q.store=?1 and q.actor=?2 and q.createdAt>=?3 and q.createdAt<=?4 and q.quantity>0 and q.metric in ('PICKED','PACKED','GROUPED')",Long.class).setParameter(1,s.store).setParameter(2,s.principal).setParameter(3,s.startedAt).setParameter(4,now).getSingleResult());return v;}
}
